import{c as t,Q as e,j as n,m as r}from"./chunks/framework.BPKcPtvA.js";const h=JSON.parse('{"title":"Peta Pelanggan","description":"","frontmatter":{},"headers":[],"relativePath":"panduan/pppoe/peta.md","filePath":"panduan/pppoe/peta.md"}'),i={name:"panduan/pppoe/peta.md"};function o(l,a,s,d,p,g){return e(),n("div",null,[...a[0]||(a[0]=[r('<h1 id="peta-pelanggan" tabindex="-1">Peta Pelanggan <a class="header-anchor" href="#peta-pelanggan" aria-label="Permalink to &quot;Peta Pelanggan&quot;">​</a></h1><p>Halaman peta menampilkan sebaran geografis semua pelanggan PPPoE yang memiliki data koordinat.</p><hr><h2 id="membuka-peta" tabindex="-1">Membuka Peta <a class="header-anchor" href="#membuka-peta" aria-label="Permalink to &quot;Membuka Peta&quot;">​</a></h2><p>Buka router → <strong>PPPoE → Peta Pelanggan</strong></p><hr><h2 id="fitur-peta" tabindex="-1">Fitur Peta <a class="header-anchor" href="#fitur-peta" aria-label="Permalink to &quot;Fitur Peta&quot;">​</a></h2><h3 id="warna-marker" tabindex="-1">Warna Marker <a class="header-anchor" href="#warna-marker" aria-label="Permalink to &quot;Warna Marker&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Warna</th><th>Status</th></tr></thead><tbody><tr><td>🟢 Hijau</td><td>Online</td></tr><tr><td>🔴 Merah</td><td>Offline</td></tr><tr><td>🟠 Oranye</td><td>Isolir</td></tr><tr><td>⚫ Abu-abu</td><td>Suspended</td></tr></tbody></table><h3 id="popup-informasi" tabindex="-1">Popup Informasi <a class="header-anchor" href="#popup-informasi" aria-label="Permalink to &quot;Popup Informasi&quot;">​</a></h3><p>Klik marker untuk melihat:</p><ul><li>Nama pelanggan</li><li>Status (dengan indikator warna)</li><li>Profil layanan</li><li>Nomor telepon</li><li><strong>Lihat Detail</strong> — link ke halaman detail pelanggan</li><li><strong>📍 Google Maps</strong> — buka koordinat di Google Maps</li></ul><h3 id="auto-refresh" tabindex="-1">Auto-Refresh <a class="header-anchor" href="#auto-refresh" aria-label="Permalink to &quot;Auto-Refresh&quot;">​</a></h3><p>Peta memperbarui status marker secara otomatis setiap <strong>30 detik</strong> tanpa perlu reload halaman.</p><h3 id="mode-gelap" tabindex="-1">Mode Gelap <a class="header-anchor" href="#mode-gelap" aria-label="Permalink to &quot;Mode Gelap&quot;">​</a></h3><p>Peta otomatis menggunakan tile gelap (CartoDB Dark) saat aplikasi dalam mode gelap.</p><hr><h2 id="menambah-koordinat-pelanggan" tabindex="-1">Menambah Koordinat Pelanggan <a class="header-anchor" href="#menambah-koordinat-pelanggan" aria-label="Permalink to &quot;Menambah Koordinat Pelanggan&quot;">​</a></h2><p>Koordinat harus diisi saat menambah atau mengedit data pelanggan:</p><ol><li>Buka <strong>Edit Pelanggan</strong></li><li>Scroll ke bagian <strong>Lokasi</strong></li><li>Isi <strong>Latitude</strong> dan <strong>Longitude</strong>, atau klik <strong>Pin di Peta</strong> untuk memilih lokasi secara visual</li><li>Simpan</li></ol><p>Pelanggan tanpa koordinat tidak akan tampil di peta.</p><hr><h2 id="statistik-peta" tabindex="-1">Statistik Peta <a class="header-anchor" href="#statistik-peta" aria-label="Permalink to &quot;Statistik Peta&quot;">​</a></h2><p>Di atas peta, tersedia chip statistik:</p><ul><li><strong>Total pelanggan</strong> — semua pelanggan di router ini</li><li><strong>Tampil di peta</strong> — yang memiliki koordinat</li><li><strong>Aktif / Isolir / Suspended</strong> — breakdown per status</li></ul>',25)])])}const m=t(i,[["render",o]]);export{h as __pageData,m as default};
